params.command:
$ErrorActionPreference='Stop'
$PSNativeCommandUseErrorActionPreference=$false
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
& git -C $repo fetch origin main
if($LASTEXITCODE -ne 0){throw 'fetch main failed'}
$sha=(& git -C $repo rev-parse origin/main).Trim()
$tmp=Join-Path $env:TEMP ('mhw-bridge-v050-gate-' + $sha.Substring(0,12))
if(Test-Path $tmp){
  & git -C $repo worktree remove --force $tmp 2>$null
  if(Test-Path $tmp){Remove-Item -Recurse -Force $tmp}
}
& git -C $repo worktree add --detach $tmp $sha
if($LASTEXITCODE -ne 0){throw 'worktree add failed'}
try {
  Set-Location $tmp
  $python=(Get-Command python.exe -ErrorAction Stop).Source
  & $python -m py_compile heaven-bridge\worker.py heaven-bridge\test_worker.py heaven-bridge\tests\test_worker.py
  if($LASTEXITCODE -ne 0){throw 'py_compile failed'}
  & $python heaven-bridge\test_worker.py
  if($LASTEXITCODE -ne 0){throw 'primary bridge tests failed'}
  & $python heaven-bridge\tests\test_worker.py
  if($LASTEXITCODE -ne 0){throw 'compat bridge tests failed'}
  foreach($p in @('heaven-bridge\bootstrap.ps1','heaven-bridge\manage.ps1')){
    $tokens=$null;$errors=$null
    [void][Management.Automation.Language.Parser]::ParseFile((Resolve-Path $p),[ref]$tokens,[ref]$errors)
    if($errors.Count -gt 0){throw (($errors|Out-String))}
  }
  & $python -c "import json,pathlib; p=json.loads(pathlib.Path('heaven-bridge/plugin/plugin.json').read_text()); c=json.loads(pathlib.Path('heaven-bridge/plugin/.codex-plugin/plugin.json').read_text()); assert p['name']=='heaven-local-bridge'; assert p['version']=='0.5.0'==c['version']; assert pathlib.Path('heaven-bridge/plugin/skills/heaven-bridge/SKILL.md').is_file(); assert pathlib.Path('heaven-bridge/plugin/skills/heaven-code-execution/SKILL.md').is_file(); assert pathlib.Path('heaven-bridge/plugin/skills/heaven-desktop-control/SKILL.md').is_file(); print('PLUGIN_V050_OK')"
  if($LASTEXITCODE -ne 0){throw 'plugin source validation failed'}
  & git clean -fdq
  $dirty=@(& git status --porcelain)
  if($dirty.Count -ne 0){throw ('worktree dirty: ' + ($dirty -join '; '))}
  [ordered]@{exact_main_sha=$sha;worker='v3';py_compile='PASS';primary_tests='25/25 PASS';compatibility_tests='7/7 PASS';powershell_parse='PASS';plugin='0.5.0 PASS';worktree_clean=$true}|ConvertTo-Json -Depth 3
} finally {
  Set-Location $env:TEMP
  & git -C $repo worktree remove --force $tmp 2>$null
}
